import {translateUi} from './i18n';
export function localizeStatisticsReport(result:{text:string;pages:{count:number}[]}){
 return result.text.split('\n').map((line,index)=>{
  const translated=translateUi(line) as string;
  // The empty marker is generated by the host only for pages with no results.
  return index>0&&result.pages[index-1]?.count===0?translated.replace('暂无匹配页面',translateUi('暂无匹配页面')):translated;
 }).join('\n');
}
